def sikker_divisjon(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return "Kan ikke dele på null"

print(sikker_divisjon(10, 3))  # 3.333...
print(sikker_divisjon(10, 0))  # Kan ikke dele på null
```

